#!/bin/sh
# PreToolUse hook on file edits: refuse to edit a file that is a copy of something else, and say
# where its source is and how a change there reaches every machine.
#
# - ~/.claude/plugins/marketplaces/<m>/ and ~/.claude/plugins/cache/<m>/: Claude Code's installed
#   copies of a marketplace and its plugins, replaced from the source on every update. An edit there
#   stays on this machine (and sync.sh stops updating vlad-skills until it's undone).
# - ~/.codex/AGENTS.md: generated by `fleet --apply`, which overwrites it.
#
# Edits made through Bash aren't seen here; sync.sh reports them at the next session start.
set -eu
. "$(dirname "$0")/lib.sh"

path=$(jq -r '.tool_input.file_path // .tool_input.notebook_path // empty')
[ -n "$path" ] || exit 0

# The path with symlinks resolved, also for a file (or directories) that don't exist yet.
resolve() {
  p=$1 rest=
  while [ ! -d "$p" ]; do
    rest="/$(basename "$p")$rest"
    p=$(dirname "$p")
  done
  printf '%s%s\n' "$(cd "$p" && pwd -P)" "$rest"
}
real=$(resolve "$path")
plugins=$(resolve "$PLUGINS")
codex=$(resolve "$HOME/.codex/AGENTS.md")

deny() {
  jq -n --arg reason "$1" \
    '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: $reason}}'
  exit 0
}

case $real in
  "$codex")
    deny "$path is generated by \`fleet --apply\` (run on the laptop), and the next run overwrites any edit.
It is two files put together: the rules every machine shares, then this machine's own part of
~/.claude/CLAUDE.md (below its fleet marker). Edit the source instead:
- this machine only: below the fleet marker in ~/.claude/CLAUDE.md, directly.
- every machine: agents/AGENTS.md. $(how_to_change agents/AGENTS.md)
Then \`fleet --apply\` on the laptop regenerates this file."
    ;;
  "$plugins"/marketplaces/*/* | "$plugins"/cache/*/*/*/*)
    kind=${real#"$plugins"/}
    kind=${kind%%/*}
    rest=${real#"$plugins/$kind"/}
    name=${rest%%/*}
    rest=${rest#*/}
    if [ "$kind" = cache ]; then
      # cache/<marketplace>/<plugin>/<version>/<file>: find the plugin's directory in the marketplace.
      plugin=${rest%%/*}
      rest=${rest#*/}
      rest=${rest#*/}
      source=$(jq -r --arg p "$plugin" '.plugins[] | select(.name == $p) | .source | strings' \
        "$(marketplace_root "$name")/.claude-plugin/marketplace.json")
      case $source in
        ./*) rest="${source#./}/$rest" ;;
        *) deny "$path is this machine's installed copy of the $plugin plugin, replaced on every plugin update.
Make the change in the plugin's own source repo instead." ;;
      esac
    fi
    if [ "$name" = "$MARKETPLACE" ]; then
      deny "$path is this machine's installed copy of the $name marketplace: Claude Code replaces it from
GitHub on every update, and an edit here never reaches git or the other machines.
$(how_to_change "$rest")"
    fi
    deny "$path is this machine's installed copy of the $name marketplace, replaced on every update.
Make the change in its source, $(marketplace_source "$name"), in $rest."
    ;;
esac
